CREATE FUNCTION public.pdc_email_ai_resolve_date_689(p_text text,p_existing date DEFAULT NULL) RETURNS date LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $d$ DECLARE x text:=lower(btrim(coalesce(p_text,''))); d int;m int;today date;c date; months text[]:=ARRAY['january','february','march','april','may','june','july','august','september','october','november','december']; BEGIN IF x~'^\d{4}-\d{2}-\d{2}$' THEN BEGIN c:=x::date; EXCEPTION WHEN others THEN RETURN NULL; END; IF to_char(c,'YYYY-MM-DD')<>x OR c<(clock_timestamp() AT TIME ZONE 'Australia/Perth')::date THEN RETURN NULL; END IF; RETURN c; END IF; IF x~'^(0?[1-9]|[12][0-9]|3[01]) (january|february|march|april|may|june|july|august|september|october|november|december)$' THEN d:=(regexp_matches(x,'^(0?[1-9]|[12][0-9]|3[01])'))[1]::int;m:=array_position(months,(regexp_matches(x,' ([a-z]+)$'))[1]); ELSIF x~'^(january|february|march|april|may|june|july|august|september|october|november|december) (0?[1-9]|[12][0-9]|3[01])$' THEN m:=array_position(months,(regexp_matches(x,'^([a-z]+)'))[1]);d:=(regexp_matches(x,' ([0-9]+)$'))[1]::int; ELSE RETURN NULL; END IF; today:=(clock_timestamp() AT TIME ZONE 'Australia/Perth')::date; BEGIN IF p_existing IS NOT NULL THEN c:=make_date(extract(year FROM p_existing)::int,m,d);IF c>=today THEN RETURN c;END IF;END IF;c:=make_date(extract(year FROM today)::int,m,d);IF c<today THEN c:=make_date(extract(year FROM today)::int+1,m,d);END IF;RETURN c;EXCEPTION WHEN others THEN RETURN NULL;END; END $d$;
