CREATE FUNCTION public.pdc_email_ai_scope_689(p_intake uuid,p_hash text,p_claim uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,auth AS $s$ DECLARE i public.pdc_email_ai_acceptance_instructions_689%rowtype;r public.pdc_email_ai_acceptance_runs_689%rowtype;q public.ai_email_intake%rowtype;c public.pdc_authenticated_provider_import_agentic_compatibility_controls_684%rowtype;BEGIN IF auth.role()<>'authenticated' OR auth.uid()<>'df7c55d9-6ba0-47f6-ba16-44d6ae2c2a4b'::uuid OR lower(btrim(coalesce(auth.jwt()->>'email','')))<>'sales@broometoyota.com.au' OR p_hash!~'^[a-f0-9]{64}$' THEN RETURN jsonb_build_object('ok',false,'code','acceptance_scope_required');END IF;SELECT * INTO i FROM public.pdc_email_ai_acceptance_instructions_689 WHERE active AND intake_id=p_intake AND source_hash=lower(p_hash) AND claim_token=p_claim;SELECT * INTO r FROM public.pdc_email_ai_acceptance_runs_689 WHERE run_id=i.run_id AND status='active';SELECT * INTO c FROM public.pdc_authenticated_provider_import_agentic_compatibility_controls_684 WHERE singleton AND enabled AND NOT task_enabled AND NOT mailbox_contacted AND NOT uid514_processed AND NOT production_writes;SELECT * INTO q FROM public.ai_email_intake WHERE id=i.intake_id AND status='processing' AND locked_by=auth.uid() AND claim_token=i.claim_token AND gateway_instance_id=c.gateway_instance_id AND provider_uid=i.provider_uid AND source_hash=i.source_hash AND coalesce(nullif(btrim(internet_message_id),''),graph_message_id)=i.message_id AND lower(btrim(sender_email))=lower(i.sender) AND recipient_mailbox='pmbcontroller@gmail.com' AND provider_authserv_id='mx.google.com' AND provider_authentication->'gmail_authentication_results'='true'::jsonb;IF i.instruction_id IS NULL OR r.run_id IS NULL OR q.id IS NULL OR NOT public.pdc_monitor_authenticated_active_scope_674(c.gateway_instance_id) THEN RETURN jsonb_build_object('ok',false,'code','acceptance_scope_required');END IF;RETURN jsonb_build_object('ok',true,'instruction_id',i.instruction_id,'run_id',r.run_id,'vehicle_id',i.vehicle_id,'booking_id',i.booking_id,'intake_id',i.intake_id,'source_hash',i.source_hash,'gateway',c.gateway_instance_id,'release_name',c.release_name,'planner_sha256',c.planner_sha256,'trust_receipt_sha256',c.trust_receipt_sha256,'actor_id',c.actor_id,'actor_email',c.actor_email,'server_application_role','importer','task_enabled',false,'mailbox_contacted',false,'uid514_processed',false,'production_writes',false);EXCEPTION WHEN others THEN RETURN jsonb_build_object('ok',false,'code','acceptance_scope_required');END $s$;
