CREATE FUNCTION public.create_pdc_email_ai_acceptance_689() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,auth,extensions AS $c$ DECLARE u uuid:=auth.uid();e text:=lower(btrim(coalesce(auth.jwt()->>'email','')));v public.vehicles%rowtype;p public.sublet_providers%rowtype;b public.pdc_sublet_booking_instances%rowtype;z jsonb;run uuid:=gen_random_uuid();ns text:='pdc-acceptance-689:'||run::text;case_key text;uidn int:=514;iid uuid;aid uuid;oid uuid;claim uuid;src text;ah text;msg text;sender text;txt text;authn jsonb:=jsonb_build_object('dkim_aligned',true,'dmarc_aligned',true,'gmail_authentication_results',true,'sender_domain','staging.pdc-workshop.example.com','spf_aligned',true);BEGIN IF NOT public.pdc_monitor_staging_guard() OR auth.role()<>'authenticated' OR u<>'df7c55d9-6ba0-47f6-ba16-44d6ae2c2a4b'::uuid OR e<>'sales@broometoyota.com.au' OR NOT public.pdc_monitor_authenticated_active_scope_674('pdc-monitor-staging-sales-uid509-v1') THEN RETURN jsonb_build_object('ok',false,'code','acceptance_campaign_scope_required');END IF;SELECT * INTO v FROM public.vehicles WHERE id='2b3b4f3b-c3a8-5a24-96cf-bcf3cf741b02'::uuid AND public.normalize_vehicle_stock_number(stock_number)='13000765' AND lifecycle_state='active' AND deleted_at IS NULL AND visible_on_board FOR UPDATE;IF NOT FOUND OR v.source_system<>'microsoft_navision' OR v.source_batch_id NOT IN('14450','37047') OR NOT EXISTS(SELECT 1 FROM public.navision_backend_records n WHERE n.id=v.source_record_id::uuid AND n.is_current AND n.record_status='current' AND n.dealer_code=v.source_batch_id AND public.normalize_vehicle_stock_number(n.normalized_data->>'batch')='13000765') OR NOT EXISTS(SELECT 1 FROM public.navision_board_activations x WHERE x.canonical_vehicle_id=v.id AND x.active AND public.normalize_vehicle_stock_number(x.activated_stock_number)='13000765') THEN RETURN jsonb_build_object('ok',false,'code','acceptance_target_identity_or_visibility_required');END IF;SELECT * INTO p FROM public.sublet_providers WHERE active AND lower(name)='customer sublet';IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','acceptance_provider_required');END IF;SELECT * INTO b FROM public.pdc_sublet_booking_instances WHERE vehicle_id=v.id AND status='active' FOR UPDATE;IF FOUND THEN IF (SELECT count(*) FROM public.pdc_sublet_booking_instances WHERE vehicle_id=v.id AND status='active')<>1 OR b.provider_id<>p.id OR b.out_date<>'2026-09-10'::date THEN RETURN jsonb_build_object('ok',false,'code','acceptance_manual_sublet_prestate_mismatch');END IF;ELSE z:=public.create_pdc_sublet_booking(v.id,v.version,p.id,'2026-09-10','2026-09-11','', 'HERMES bounded staging acceptance fixture');IF coalesce((z->>'ok')::boolean,false) IS NOT TRUE THEN RETURN jsonb_build_object('ok',false,'code','acceptance_manual_sublet_setup_failed','detail',z);END IF;SELECT * INTO b FROM public.pdc_sublet_booking_instances WHERE vehicle_id=v.id AND status='active';END IF;INSERT INTO public.vehicle_work_items(vehicle_id,work_key,required,completed,notes,updated_at) VALUES(v.id,'sublet',true,false,'Required only after manual canonical Sublet booking; HERMES acceptance',clock_timestamp()) ON CONFLICT(vehicle_id,work_key) DO UPDATE SET required=true WHERE NOT public.vehicle_work_items.completed;INSERT INTO public.pdc_email_ai_acceptance_runs_689(namespace,actor_id,actor_email,gateway,release_name,source_sha,manifest_sha256,planner_sha256,trust_receipt_sha256,target_vehicle_id,status,case_count) VALUES(ns,u,e,'pdc-monitor-staging-sales-uid509-v1','pdc-monitor-staging-m502-2026.08.44','e850c319989d98b45b95a28aa815d78e2c2e3a4b','d48b49f6598a99fbef99fc4f0d0ab36b8b47576b8ff7cd8ecd2cb64d6cfed58d','7e08a00bc099610aa919bb7c3089ef84b91a74bafd69f95fab06bfccfdf67348','e3e30ace04e676e34f271b161283b9e4764d462f76428d63826fa3cb153d7227',v.id,'active',6);FOREACH case_key IN ARRAY ARRAY['parts_eta','parts_complete','sublet_booking_date','multi_action','exact_replay','ambiguous_negative'] LOOP uidn:=uidn+1;iid:=gen_random_uuid();aid:=gen_random_uuid();oid:=gen_random_uuid();claim:=gen_random_uuid();sender:='pdc-acceptance-'||replace(run::text,'-','')||'-'||case_key||'@staging.pdc-workshop.example.com';msg:='<pdc-acceptance-689-'||replace(run::text,'-','')||'-'||case_key||'@staging.invalid>';src:=encode(extensions.digest(convert_to(ns||'|'||case_key,'UTF8'),'sha256'),'hex');ah:=encode(extensions.digest(convert_to(ns||'|attachment|'||case_key,'UTF8'),'sha256'),'hex');txt:=case case_key when 'parts_eta' then '13000765 parts ETA is 12 June.' when 'parts_complete' then '13000765 parts are complete.' when 'sublet_booking_date' then '13000765 sublet is booked for 15 September.' when 'multi_action' then '13000765 parts ETA is 15 September. 13000765 parts are complete. 13000765 sublet is booked for 15 September.' when 'exact_replay' then '13000765 parts ETA is 12 June.' else '13000765 parts may be complete or perhaps not.' end;INSERT INTO public.ai_email_intake(id,status,subject,sender_email,sender_name,received_at,graph_message_id,graph_thread_id,internet_message_id,attachment_names,raw_body,parsed_text,extracted_data,confidence,warnings,processing_result,monitored_mailbox_id,recipient_mailbox,queue_attempts,permanent_failure,provider_uid,source_hash,claim_token,gateway_instance_id,provider_authserv_id,provider_authentication,locked_at,locked_by) VALUES(iid,'processing','PDC Acceptance 689 '||case_key,sender,'PDC Acceptance Fixture',clock_timestamp(),msg,ns||'|'||case_key,msg,ARRAY[case_key||'.pdf'],txt,txt,'{}'::jsonb,1,'{}','{"test_fixture":true,"campaign":"689"}'::jsonb,'12fe383d-5c1e-5801-96e4-f67cf3e3bb57','pmbcontroller@gmail.com',0,false,'imap_uid:'||uidn,src,claim,'pdc-monitor-staging-sales-uid509-v1','mx.google.com',authn,clock_timestamp(),u);INSERT INTO public.ai_email_attachments(id,intake_id,file_name,content_type,size_bytes,storage_path,text_extraction_status,extracted_text,source_hash) VALUES(aid,iid,case_key||'.pdf','application/pdf',1024,'pdc-email-intake-private/acceptance-689/'||ah||'.pdf','extracted',txt,ah);INSERT INTO public.pdc_provider_email_observations(observation_id,contract_version,intake_id,attachment_id,parent_source_hash,attachment_source_hash,provider_message_id,provider_authserv_id,authentication,request_sha256,attested_by,attested_authority) VALUES(oid,'159.2',iid,aid,src,ah,msg,'mx.google.com',authn,encode(extensions.digest(convert_to(ns||'|observation|'||case_key,'UTF8'),'sha256'),'hex'),u,'authenticated_acceptance_689');INSERT INTO public.pdc_email_ai_acceptance_instructions_689(run_id,case_key,intake_id,attachment_id,observation_id,vehicle_id,booking_id,provider_uid,source_hash,attachment_hash,claim_token,message_id,sender,natural_language) VALUES(run,case_key,iid,aid,oid,v.id,case when case_key IN('sublet_booking_date','multi_action') then b.booking_id else NULL end,'imap_uid:'||uidn,src,ah,claim,msg,sender,txt);END LOOP;UPDATE public.pdc_email_ai_acceptance_runs_689 SET result=jsonb_build_object('manual_booking_id',b.booking_id,'manual_booking_date','2026-09-10','provider_id',p.id,'fixture_count',6,'provider_uid_floor',515,'synthetic_fixture',true,'production_writes',false,'task_enabled',false,'mailbox_contacted',false) WHERE run_id=run;RETURN jsonb_build_object('ok',true,'code','acceptance_campaign_created','run_id',run,'target_vehicle_id',v.id,'target_stock_number','13000765','manual_booking_id',b.booking_id,'manual_booking_date','2026-09-10','provider_id',p.id,'fixture_count',6,'provider_uid_floor',515,'production_writes',false,'task_enabled',false,'mailbox_contacted',false,'fixtures',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY provider_uid),'[]'::jsonb) FROM public.pdc_email_ai_acceptance_instructions_689 x WHERE x.run_id=run));EXCEPTION WHEN others THEN RETURN jsonb_build_object('ok',false,'code','acceptance_campaign_create_failed');END $c$;
