CREATE FUNCTION public.record_pdc_email_ai_acceptance_plan_689(p_intake uuid,p_hash text,p_claim uuid,p_instruction text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,auth,extensions AS $p$
DECLARE s jsonb; f public.pdc_email_ai_acceptance_instructions_689%rowtype; old public.pdc_email_ai_acceptance_plans_689%rowtype; x text:=btrim(coalesce(p_instruction,'')); l text:=lower(btrim(coalesce(p_instruction,''))); acts jsonb:='[]'::jsonb; dtext text; d date; n integer:=0; ph text; h text;
BEGIN
 s:=public.pdc_email_ai_scope_689(p_intake,p_hash,p_claim); IF s->>'ok'<>'true' THEN RETURN s; END IF;
 SELECT * INTO f FROM public.pdc_email_ai_acceptance_instructions_689 WHERE instruction_id=(s->>'instruction_id')::uuid;
 SELECT * INTO old FROM public.pdc_email_ai_acceptance_plans_689 WHERE instruction_id=f.instruction_id;
 IF FOUND THEN IF old.instruction<>x THEN RETURN jsonb_build_object('ok',false,'code','acceptance_plan_replay_conflict'); END IF; RETURN jsonb_build_object('ok',true,'code','acceptance_plan_replayed','plan_id',old.plan_id,'plan_hash',old.plan_hash,'evidence_hash',old.evidence_hash,'actions',old.actions,'replay',true); END IF;
 IF length(x)<3 OR x~'[[:cntrl:]]' OR l~'(^|[[:space:]])(if|maybe|perhaps|possibly|not|pending|uncertain|could|would|should|might)([[:space:]]|$)' OR position('13000765' in l)=0 THEN
   acts:=jsonb_build_array(jsonb_build_object('action_no',1,'action_type','unparsed','evidence',x,'disposition','genuinely_ambiguous','reason','Genuinely unclear or non-unique Stock identity'));
 ELSE
   IF position('parts eta is ' in l)>0 THEN dtext:=btrim(split_part(split_part(l,'parts eta is ',2),'.',1)); d:=public.pdc_email_ai_resolve_date_689(dtext,NULL); n:=n+1; acts:=acts||jsonb_build_array(jsonb_build_object('action_no',n,'action_type',case when d is null then 'unparsed' else 'parts_eta' end,'evidence',x,'date_text',dtext,'resolved_date',d,'reason',case when d is null then 'Genuinely unclear or invalid business date' else 'Next non-past staging date' end)); END IF;
   IF l like '%parts are complete%' OR l like '%parts is complete%' OR l like '%parts completed%' THEN n:=n+1; acts:=acts||jsonb_build_array(jsonb_build_object('action_no',n,'action_type','parts_complete','evidence',x,'reason','Exact Parts complete assertion')); END IF;
   IF position('sublet is booked for ' in l)>0 OR position('sub-let is booked for ' in l)>0 THEN dtext:=btrim(split_part(split_part(replace(l,'sub-let is booked for ','sublet is booked for '),'sublet is booked for ',2),'.',1)); SELECT out_date INTO d FROM public.pdc_sublet_booking_instances WHERE booking_id=f.booking_id AND status='active'; d:=public.pdc_email_ai_resolve_date_689(dtext,d); n:=n+1; acts:=acts||jsonb_build_array(jsonb_build_object('action_no',n,'action_type',case when d is null then 'unparsed' else 'sublet_booking_date' end,'evidence',x,'date_text',dtext,'resolved_date',d,'reason',case when d is null then 'Genuinely unclear or invalid business date' else 'Existing booking year preserved when valid and non-past' end)); END IF;
   IF n=0 THEN acts:=jsonb_build_array(jsonb_build_object('action_no',1,'action_type','unparsed','evidence',x,'disposition','genuinely_ambiguous','reason','No exact supported canonical action recognized')); END IF;
 END IF;
 ph:=encode(extensions.digest(convert_to(jsonb_build_object('contract','pdc-email-ai-natural-language-689.1','intake_id',f.intake_id,'evidence_hash',f.source_hash,'instruction',x,'actions',acts)::text,'UTF8'),'sha256'),'hex');
 FOR n IN 1..jsonb_array_length(acts) LOOP h:=encode(extensions.digest(convert_to(jsonb_build_object('contract','pdc-email-ai-natural-language-689.1','source_hash',f.source_hash,'plan_hash',ph,'action',acts->(n-1))::text,'UTF8'),'sha256'),'hex'); acts:=jsonb_set(acts,ARRAY[(n-1)::text],(acts->(n-1))||jsonb_build_object('action_hash',h),true); END LOOP;
 INSERT INTO public.pdc_email_ai_acceptance_plans_689(instruction_id,run_id,intake_id,evidence_hash,plan_hash,instruction,actions) VALUES(f.instruction_id,f.run_id,f.intake_id,f.source_hash,ph,x,acts) RETURNING * INTO old;
 RETURN jsonb_build_object('ok',true,'code','acceptance_plan_recorded','plan_id',old.plan_id,'plan_hash',old.plan_hash,'evidence_hash',old.evidence_hash,'actions',old.actions,'replay',false);
EXCEPTION WHEN others THEN RETURN jsonb_build_object('ok',false,'code','acceptance_plan_invalid');
END $p$;
