CREATE FUNCTION public.execute_pdc_email_ai_acceptance_action_689(p_intake uuid,p_hash text,p_claim uuid,p_plan text,p_action text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,auth,extensions AS $x$ DECLARE s jsonb;f public.pdc_email_ai_acceptance_instructions_689%rowtype;pl public.pdc_email_ai_acceptance_plans_689%rowtype;old public.pdc_email_ai_acceptance_action_receipts_689%rowtype;a jsonb;v public.vehicles%rowtype;pu public.vehicle_parts_updates%rowtype;wi public.vehicle_work_items%rowtype;b public.pdc_sublet_booking_instances%rowtype;r jsonb;before jsonb;after jsonb;d date;disp text;why text;eff int:=0;no int;BEGIN s:=public.pdc_email_ai_scope_689(p_intake,p_hash,p_claim);IF s->>'ok'<>'true' THEN RETURN s;END IF;SELECT * INTO f FROM public.pdc_email_ai_acceptance_instructions_689 WHERE instruction_id=(s->>'instruction_id')::uuid;SELECT * INTO pl FROM public.pdc_email_ai_acceptance_plans_689 WHERE instruction_id=f.instruction_id AND plan_hash=lower(btrim(p_plan));IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','acceptance_plan_not_found');END IF;SELECT * INTO old FROM public.pdc_email_ai_acceptance_action_receipts_689 WHERE plan_id=pl.plan_id AND action_hash=lower(btrim(p_action));IF FOUND THEN RETURN jsonb_build_object('ok',true,'code','acceptance_action_replayed','action_id',old.action_id,'action_hash',old.action_hash,'action_type',old.action_type,'resolved_date',old.resolved_date,'disposition',old.disposition,'reason',old.reason,'before_state',old.before_state,'after_state',old.after_state,'effect_count',old.effect_count,'replay',true);END IF;SELECT action_no,value INTO no,a FROM jsonb_array_elements(pl.actions) WITH ORDINALITY q(value,action_no) WHERE value->>'action_hash'=lower(btrim(p_action));IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','acceptance_action_not_in_plan');END IF;SELECT * INTO v FROM public.vehicles WHERE id=f.vehicle_id FOR UPDATE;before:=jsonb_build_object('vehicle',to_jsonb(v));disp:=NULL;why:=NULL;IF a->>'action_type'='unparsed' OR (a->>'resolved_date' IS NULL AND a->>'action_type' IN('parts_eta','sublet_booking_date')) THEN disp:='genuinely_ambiguous';why:=coalesce(a->>'reason','Genuinely unclear instruction');ELSIF a->>'action_type'='parts_eta' THEN d:=(a->>'resolved_date')::date;SELECT * INTO pu FROM public.vehicle_parts_updates WHERE vehicle_id=v.id ORDER BY updated_at DESC,id DESC LIMIT 1;IF pu.worst_eta=d THEN disp:='already_correct';why:='Parts ETA already equals resolved ISO date';ELSE r:=public.update_pdc_parts_eta(v.id,v.version,d);IF coalesce((r->>'ok')::boolean,false) THEN disp:='applied_and_verified';why:='Canonical Parts ETA applied and read back';eff:=1;ELSE disp:='blocked_with_exact_reason';why:=coalesce(r->>'error',r->>'code','Canonical Parts ETA rejected');END IF;END IF;ELSIF a->>'action_type'='parts_complete' THEN SELECT * INTO pu FROM public.vehicle_parts_updates WHERE vehicle_id=v.id ORDER BY updated_at DESC,id DESC LIMIT 1;SELECT * INTO wi FROM public.vehicle_work_items WHERE vehicle_id=v.id AND upper(work_key)='PARTS' FOR UPDATE;IF coalesce(wi.completed,false) AND coalesce(pu.parts_received,false) THEN disp:='already_correct';why:='Canonical Parts state already complete';ELSIF pu.worst_eta IS NULL THEN disp:='blocked_with_exact_reason';why:='parts_eta_required';ELSE BEGIN r:=public.mark_pdc_parts_complete(v.id,v.version);IF coalesce((r->>'ok')::boolean,false) AND coalesce(r->>'code','') IN('parts_completed','replayed') THEN disp:=case when coalesce((r#>>'{data,changed}')::boolean,false) then 'applied_and_verified' else 'already_correct' end;why:='Canonical Parts Complete applied and read back';eff:=case when disp='applied_and_verified' then 1 else 0 end;ELSE disp:='blocked_with_exact_reason';why:=coalesce(r->>'error',r->>'code','Canonical Parts Complete rejected');END IF;EXCEPTION WHEN others THEN disp:='blocked_with_exact_reason';why:=sqlerrm;END;END IF;ELSIF a->>'action_type'='sublet_booking_date' THEN d:=(a->>'resolved_date')::date;SELECT * INTO b FROM public.pdc_sublet_booking_instances WHERE booking_id=f.booking_id AND status='active' FOR UPDATE;IF NOT FOUND OR (SELECT count(*) FROM public.pdc_sublet_booking_instances WHERE vehicle_id=v.id AND status='active')<>1 THEN disp:='blocked_with_exact_reason';why:='sublet_existing_booking_required';ELSIF b.out_date=d THEN disp:='already_correct';why:='Existing canonical Sublet booking already equals resolved ISO date';ELSE r:=public.update_pdc_sublet_booking(b.booking_id,b.version,d,b.expected_return_date,b.notes);IF coalesce((r->>'ok')::boolean,false) THEN disp:='applied_and_verified';why:='Existing canonical Sublet booking updated; no provider or booking created';eff:=1;ELSE disp:='blocked_with_exact_reason';why:=coalesce(r->>'error',r->>'code','Canonical Sublet update rejected');END IF;END IF;ELSE disp:='genuinely_ambiguous';why:='Unsupported canonical action';END IF;SELECT * INTO v FROM public.vehicles WHERE id=f.vehicle_id;SELECT * INTO pu FROM public.vehicle_parts_updates WHERE vehicle_id=v.id ORDER BY updated_at DESC,id DESC LIMIT 1;SELECT * INTO wi FROM public.vehicle_work_items WHERE vehicle_id=v.id AND upper(work_key)='PARTS';SELECT * INTO b FROM public.pdc_sublet_booking_instances WHERE vehicle_id=v.id AND status='active' ORDER BY out_date,booking_id LIMIT 1;after:=jsonb_build_object('vehicle',to_jsonb(v),'parts',jsonb_build_object('eta',pu.worst_eta,'received',coalesce(pu.parts_received,false),'completed',coalesce(wi.completed,false)),'sublet',case when b.booking_id IS NULL then '{}'::jsonb else jsonb_build_object('booking_id',b.booking_id,'provider_id',b.provider_id,'out_date',b.out_date,'version',b.version,'status',b.status) end);INSERT INTO public.pdc_email_ai_acceptance_action_receipts_689(plan_id,instruction_id,action_no,action_hash,action_type,requested,resolved_date,disposition,reason,before_state,after_state,effect_count) VALUES(pl.plan_id,f.instruction_id,no,p_action,a->>'action_type',a,d,disp,why,before,after,eff);SELECT * INTO old FROM public.pdc_email_ai_acceptance_action_receipts_689 WHERE action_hash=p_action;RETURN jsonb_build_object('ok',true,'code','acceptance_action_executed','action_id',old.action_id,'action_hash',old.action_hash,'action_no',old.action_no,'action_type',old.action_type,'resolved_date',old.resolved_date,'disposition',old.disposition,'reason',old.reason,'before_state',old.before_state,'after_state',old.after_state,'effect_count',old.effect_count,'replay',false);EXCEPTION WHEN unique_violation THEN SELECT * INTO old FROM public.pdc_email_ai_acceptance_action_receipts_689 WHERE action_hash=p_action;IF FOUND THEN RETURN jsonb_build_object('ok',true,'code','acceptance_action_replayed','action_id',old.action_id,'action_hash',old.action_hash,'disposition',old.disposition,'effect_count',old.effect_count,'replay',true);END IF;RETURN jsonb_build_object('ok',false,'code','acceptance_action_replay_conflict');END $x$;
