CREATE FUNCTION public.finalize_pdc_email_ai_acceptance_689(p_intake uuid,p_hash text,p_claim uuid,p_plan text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,auth,extensions AS $f$ DECLARE s jsonb;f public.pdc_email_ai_acceptance_instructions_689%rowtype;p public.pdc_email_ai_acceptance_plans_689%rowtype;rows jsonb;tot int;n int;blocked int;amb int;applied int;outcome text;res jsonb;h text;old public.pdc_email_ai_acceptance_final_receipts_689%rowtype;BEGIN s:=public.pdc_email_ai_scope_689(p_intake,p_hash,p_claim);IF s->>'ok'<>'true' THEN RETURN s;END IF;SELECT * INTO f FROM public.pdc_email_ai_acceptance_instructions_689 WHERE instruction_id=(s->>'instruction_id')::uuid;SELECT * INTO p FROM public.pdc_email_ai_acceptance_plans_689 WHERE instruction_id=f.instruction_id AND plan_hash=lower(btrim(p_plan));IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','acceptance_plan_not_found');END IF;SELECT count(*) INTO tot FROM jsonb_array_elements(p.actions);SELECT count(*) INTO n FROM public.pdc_email_ai_acceptance_action_receipts_689 WHERE plan_id=p.plan_id;IF n<>tot THEN RETURN jsonb_build_object('ok',false,'code','acceptance_actions_not_terminal','expected',tot,'actual',n);END IF;SELECT coalesce(jsonb_agg(jsonb_build_object('action_no',a.action_no,'action_hash',a.action_hash,'action_type',a.action_type,'resolved_date',a.resolved_date,'disposition',a.disposition,'reason',a.reason,'effect_count',a.effect_count) ORDER BY a.action_no),'[]'::jsonb) INTO rows FROM public.pdc_email_ai_acceptance_action_receipts_689 a WHERE a.plan_id=p.plan_id;SELECT count(*) FILTER(WHERE disposition='blocked_with_exact_reason'),count(*) FILTER(WHERE disposition='genuinely_ambiguous'),count(*) FILTER(WHERE disposition='applied_and_verified') INTO blocked,amb,applied FROM public.pdc_email_ai_acceptance_action_receipts_689 WHERE plan_id=p.plan_id;outcome:=case when amb>0 then 'genuinely_ambiguous' when blocked>0 then 'blocked_with_exact_reason' when applied>0 then 'applied_and_verified' else 'already_correct' end;res:=jsonb_build_object('ok',blocked=0 AND amb=0,'code','acceptance_plan_finalized','outcome',outcome,'evidence_hash',p.evidence_hash,'plan_hash',p.plan_hash,'vehicle_id',f.vehicle_id,'target_stock_number','13000765','actions',rows,'dependency_order',case when tot>1 then ARRAY['parts_eta','parts_complete','sublet_booking_date'] else ARRAY[]::text[] END,'resolved_dates_in_plan',p.actions,'booking_created',false,'provider_created',false,'location_changed',false,'task_enabled',false,'mailbox_contacted',false,'uid514_processed',false,'production_writes',false);h:=encode(extensions.digest(convert_to(res::text,'UTF8'),'sha256'),'hex');INSERT INTO public.pdc_email_ai_acceptance_final_receipts_689(plan_id,instruction_id,evidence_hash,plan_hash,outcome,result,result_hash) VALUES(p.plan_id,f.instruction_id,p.evidence_hash,p.plan_hash,outcome,res,h) ON CONFLICT(plan_id) DO NOTHING;SELECT * INTO old FROM public.pdc_email_ai_acceptance_final_receipts_689 WHERE plan_id=p.plan_id;RETURN jsonb_build_object('ok',true,'code','acceptance_finalized','final_id',old.final_id,'outcome',old.outcome,'result',old.result,'result_hash',old.result_hash,'replay',old.result_hash=h);END $f$;
REVOKE ALL ON FUNCTION public.finalize_pdc_email_ai_acceptance_689(uuid,text,uuid,text) FROM public,anon,service_role,pdc_email_monitor;GRANT EXECUTE ON FUNCTION public.finalize_pdc_email_ai_acceptance_689(uuid,text,uuid,text) TO authenticated;

CREATE FUNCTION public.read_pdc_email_ai_acceptance_689(p_run uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,auth AS $r$ DECLARE x public.pdc_email_ai_acceptance_runs_689%rowtype;BEGIN IF auth.role()<>'authenticated' OR auth.uid()<>'df7c55d9-6ba0-47f6-ba16-44d6ae2c2a4b'::uuid THEN RETURN jsonb_build_object('ok',false,'code','acceptance_read_scope_required');END IF;SELECT * INTO x FROM public.pdc_email_ai_acceptance_runs_689 WHERE run_id=p_run AND actor_id=auth.uid();IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','acceptance_run_not_found');END IF;RETURN jsonb_build_object('ok',true,'code','acceptance_readback','run_id',x.run_id,'status',x.status,'case_count',x.case_count,'result',x.result,'instructions',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.provider_uid),'[]'::jsonb) FROM public.pdc_email_ai_acceptance_instructions_689 i WHERE i.run_id=x.run_id),'plans',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.created_at),'[]'::jsonb) FROM public.pdc_email_ai_acceptance_plans_689 p WHERE p.run_id=x.run_id),'actions',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.created_at),'[]'::jsonb) FROM public.pdc_email_ai_acceptance_action_receipts_689 a JOIN public.pdc_email_ai_acceptance_plans_689 p ON p.plan_id=a.plan_id WHERE p.run_id=x.run_id),'finals',(SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY f.created_at),'[]'::jsonb) FROM public.pdc_email_ai_acceptance_final_receipts_689 f JOIN public.pdc_email_ai_acceptance_plans_689 p ON p.plan_id=f.plan_id WHERE p.run_id=x.run_id),'production_writes',false,'task_enabled',false,'mailbox_contacted',false,'uid514_processed',false);END $r$;
REVOKE ALL ON FUNCTION public.read_pdc_email_ai_acceptance_689(uuid) FROM public,anon,service_role,pdc_email_monitor;GRANT EXECUTE ON FUNCTION public.read_pdc_email_ai_acceptance_689(uuid) TO authenticated;

