ersion,'provider_id',b.provider_id,'booking_id',b.booking_id) FROM public.pdc_sublet_booking_instances b WHERE b.vehicle_id=v.id AND b.status='active' ORDER BY b.out_date,b.booking_id LIMIT 1),'{}'::jsonb),'sublet_bookings',coalesce((SELECT jsonb_agg(jsonb_build_object('booking_id',b.booking_id,'vehicle_id',b.vehicle_id,'vehicle_version',b.vehicle_version,'provider_id',b.provider_id,'provider_name',b.provider_name,'provider_email',b.provider_email,'out_date',b.out_date,'expected_return_date',b.expected_return_date,'status',b.status,'version',b.version,'notes',b.notes,'updated_at',b.updated_at) ORDER BY b.out_date,b.booking_id) FROM public.pdc_sublet_booking_instances b WHERE b.vehicle_id=v.id),'[]'::jsonb),'sublet_active_count',(SELECT count(*) FROM public.pdc_sublet_booking_instances b WHERE b.vehicle_id=v.id AND b.status='active')) INTO t FROM public.vehicles v WHERE v.id='2b3b4f3b-c3a8-5a24-96cf-bcf3cf741b02'::uuid AND public.normalize_vehicle_stock_number(v.stock_number)='13000765' AND v.lifecycle_state='active' AND v.deleted_at IS NULL AND v.visible_on_board AND v.source_system='microsoft_navision' AND v.source_batch_id IN('14450','37047') AND v.source_record_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.navision_backend_records n WHERE n.id=v.source_record_id::uuid AND n.is_current AND n.record_status='current' AND n.dealer_code=v.source_batch_id AND public.normalize_vehicle_stock_number(n.normalized_data->>'batch')='13000765') AND EXISTS(SELECT 1 FROM public.navision_board_activations a WHERE a.canonical_vehicle_id=v.id AND a.active AND public.normalize_vehicle_stock_number(a.activated_stock_number)='13000765');SELECT coalesce(jsonb_agg(q ORDER BY coalesce(q->>'stock_number',q->>'id')),'[]'::jsonb) INTO rows FROM (SELECT value q FROM jsonb_array_elements(coalesce(r#>'{data,vehicles}','[]'::jsonb)) u UNION ALL SELECT t WHERE t IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(r#>'{data,vehicles}','[]'::jsonb)) u WHERE u->>'id'=t->>'id')) z;RETURN jsonb_set(r,'{data,vehicles}',rows,true);END $b$;
